/**
 * Site structure, from "Selected sitemap: Concept A (v2)" in FigJam.
 * Paths are language-neutral; French URLs get a /fr prefix.
 *
 * `stub: true` pages are generated by src/pages/[...slug].astro.
 * When a page gets its own .astro file, set `stub: false` for it here.
 */
import type { Lang } from '../i18n/ui';

type Text = Record<Lang, string>;

export interface Page {
  path: string;
  /** Short label used in menus. */
  nav: Text;
  /** Full page title (H1 and <title>). */
  title: Text;
  group?: string;
  stub: boolean;
}

export interface Group {
  id: string;
  label: Text;
}

export interface Section {
  id: string;
  base: string;
  label: Text;
  groups?: Group[];
  pages: Page[];
}

const p = (path: string, nav: Text, title: Text = nav, group?: string): Page => ({
  path,
  nav,
  title,
  group,
  stub: true,
});

