/** Pages outside the main menus (demo flow and footer). */
export const otherPages: Page[] = [
  p('/demo/', { en: 'Request a demo', fr: 'Demander une démo' }),
  p('/demo/thanks/', { en: 'Thank you', fr: 'Merci' }, { en: 'Thank you', fr: 'Merci' }),
  p('/privacy/', { en: 'Privacy policy', fr: 'Politique de confidentialité' }),
  p('/terms/', { en: 'Terms of use', fr: "Conditions d'utilisation" }),
  p('/accessibility/', { en: 'Accessibility', fr: 'Accessibilité' }),
];

export const footerLinks = ['/about/contact/', '/privacy/', '/terms/', '/accessibility/'];

export const allPages: Page[] = [...sections.flatMap((s) => s.pages), ...otherPages];

export function findPage(path: string): Page | undefined {
  return allPages.find((pg) => pg.path === path);
}

export function findSection(path: string): Section | undefined {
  return sections.find((s) => path.startsWith(s.base));
}
